import csv
catal=[r for r in csv.DictReader(open(CATALOG_CSV))]
# map ts to point info
targets={}
import re
data=open(GRAPH_TTL).read()
for m in re.finditer(r'bldg:([A-Za-z0-9_.]+)\s+a\s+(brick:[A-Za-z_]+)\s*;', data):
    seg=data[m.end():m.end()+400]
    ref=re.search(r'hasExternalReference\s*<urn:buildgraph:tsref:([0-9a-f-]+)>',seg)
    if ref and m.group(2) in ('brick:Power_Sensor','brick:Electric_Power_Sensor'):
        poof=re.search(r'brick:isPointOf\s+bldg:([A-Za-z0-9_.]+)',seg)
        targets[ref.group(1)]=(poof.group(1) if poof else None)
info={}
for r in catal:
    ts=r['timeseries_id']
    if ts in targets:
        info[ts]=(targets[ts],r['point_class'],r['unit'],r['quantity_kind'])
for t,i in info.items():
    print(t,i)

